from collections import deque
def transform(g):
    h,w=len(g),len(g[0])
    bg=g[0][0]
    # count neighbor colors
    def same_neighbors(y,x,c):
        n=0
        for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
            ny,nx=y+dy,x+dx
            if 0<=ny<h and 0<=nx<w and g[ny][nx]==c: n+=1
        return n
    a=[row[:] for row in g]
    # remove isolated pixels (noise)
    for i in range(h):
        for j in range(w):
            if same_neighbors(i,j,g[i][j])==0: a[i][j]=bg
    # find components, fill bboxes
    rects=[]
    seen=[[False]*w for _ in range(h)]
    for i in range(h):
        for j in range(w):
            if seen[i][j] or a[i][j]==bg: continue
            c=a[i][j]; q=deque([(i,j)]); seen[i][j]=True; comp=[]
            while q:
                y,x=q.popleft(); comp.append((y,x))
                for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<h and 0<=nx<w and not seen[ny][nx] and a[ny][nx]==c:
                        seen[ny][nx]=True; q.append((ny,nx))
            if len(comp)>=6:
                ys=[p[0] for p in comp]; xs=[p[1] for p in comp]
                rects.append((c,min(ys),max(ys),min(xs),max(xs)))
    out=[[bg]*w for _ in range(h)]
    for c,y0,y1,x0,x1 in rects:
        for y in range(y0,y1+1):
            for x in range(x0,x1+1): out[y][x]=c
    return out

